WITH all_weekend AS (
    SELECT COUNT(*) as total FROM service_requests WHERE EXTRACT(DOW FROM opened_at) IN (0, 6)
),
afternoon_weekend AS (
    SELECT COUNT(*) as afternoon_total 
    FROM service_requests 
    WHERE EXTRACT(DOW FROM opened_at) IN (0, 6) 
      AND EXTRACT(HOUR FROM opened_at) >= 12 AND EXTRACT(HOUR FROM opened_at) < 18
)
SELECT * FROM all_weekend, afternoon_weekend;

